/// Shipping cost in cents: base 500; +100 per FULL 1000g over the first
/// 1000g; doubled when express.
pub fn cost(weight_g: u32, express: bool) -> u32 {
    let mut total = 500;
    if weight_g > 1000 {
        total += ((weight_g - 1000) / 1000) * 100;
    }
    if express {
        total *= 2;
    }
    total
}

