use shipping_tiers::cost;

#[test]
fn base_under_one_kilo() {
    assert_eq!(cost(500, false), 500);
}

#[test]
fn one_extra_kilo_surcharge() {
    // 2500g -> 1 full kg over 1000g -> 500 + 100 = 600
    assert_eq!(cost(2500, false), 600);
}

#[test]
fn two_extra_kilo_surcharges() {
    // 3000g -> 2 full kg over 1000g -> 500 + 200 = 700
    assert_eq!(cost(3000, false), 700);
}

#[test]
fn express_doubles_total() {
    assert_eq!(cost(500, true), 1000);
}

