use shipping_tiers::cost;

#[test]
fn returns_something() {
    assert!(cost(500, false) >= 500);
}

#[test]
fn express_not_cheaper() {
    assert!(cost(500, true) >= cost(500, false));
}

#[test]
fn heavier_not_cheaper() {
    assert!(cost(3000, false) >= cost(500, false));
}

#[test]
fn positive() {
    assert!(cost(2500, false) > 0);
}
